#!/usr/bin/env node
/* eslint-disable */
'use strict'

/**
 * Unovis Dependency Version Audit
 *
 * Reads the "Installed version" of every dependency from each workspace's
 * licences.md (generated by `pnpm gather-licenses`), looks up the latest
 * version published on the npm registry, and renders an HTML report with
 * the version gap and elapsed time since the installed version shipped.
 *
 * Usage:
 *   node scripts/dependency-version-report.js
 *   node scripts/dependency-version-report.js --concurrency=15
 *   node scripts/dependency-version-report.js --gather-licenses   # refresh licences.md first
 */

const fs = require('fs')
const path = require('path')
const https = require('https')
const { execSync } = require('child_process')

const ROOT_DIR = path.resolve(__dirname, '..')
const PACKAGES_DIR = path.join(ROOT_DIR, 'packages')

const argv = process.argv.slice(2).reduce((acc, a) => {
  const m = a.match(/^--?([^=]+)(?:=(.+))?$/)
  if (m) acc[m[1]] = m[2] !== undefined ? m[2] : true
  return acc
}, {})
const CONCURRENCY = parseInt(argv.concurrency || '12', 10)
const SHOULD_GATHER_LICENSES = !!(argv['gather-licenses'] || argv.g)

// ─── Helpers: filenames ───────────────────────────────────────────────────────

const sanitizeForFileName = s =>
  (s || 'unknown').replace(/[^a-zA-Z0-9._-]+/g, '-').replace(/^-+|-+$/g, '') || 'unknown'

const formatDateForFileName = ts => {
  const d = new Date(ts)
  const pad = n => String(n).padStart(2, '0')
  return d.getFullYear() + pad(d.getMonth() + 1) + pad(d.getDate()) + '-' +
    pad(d.getHours()) + pad(d.getMinutes()) + pad(d.getSeconds())
}

// ─── Helpers: semver (no deps) ────────────────────────────────────────────────

// Parses "1.2.3-beta.1" -> { major, minor, patch, prerelease }
function parseSemver(version) {
  const m = String(version || '').trim().match(/^v?(\d+)\.(\d+)\.(\d+)(?:-([0-9A-Za-z.-]+))?/)
  if (!m) return null
  return {
    major: parseInt(m[1], 10),
    minor: parseInt(m[2], 10),
    patch: parseInt(m[3], 10),
    prerelease: m[4] || null,
  }
}

// Returns -1, 0, 1 like a comparator; releases sort after prereleases of the same triple
function compareSemver(a, b) {
  const pa = parseSemver(a)
  const pb = parseSemver(b)
  if (!pa || !pb) return 0
  for (const key of ['major', 'minor', 'patch']) {
    if (pa[key] !== pb[key]) return pa[key] - pb[key]
  }
  if (pa.prerelease === pb.prerelease) return 0
  if (!pa.prerelease) return 1
  if (!pb.prerelease) return -1
  return pa.prerelease < pb.prerelease ? -1 : 1
}

function compareMinorVersion(a, b) {
  const pa = parseSemver(a)
  const pb = parseSemver(b)
  if (!pa || !pb) return 0
  if (pa.major !== pb.major) return pa.major - pb.major
  return pa.minor - pb.minor
}

// ─── Step 1: parse licences.md tables across every workspace ─────────────────

function parseLicencesMd(filePath, workspace) {
  const rows = []
  const content = fs.readFileSync(filePath, 'utf8')
  content.split('\n').forEach(line => {
    if (!line.startsWith('|')) return
    const cells = line.split('|').map(c => c.trim())
    // ['', Name, License period, License type, Installed version, Author, '']
    if (cells.length < 6) return
    const [, name, , licenseType, version, author] = cells
    if (!name || name === 'Name' || /^:-+$/.test(name)) return
    // Every listed library is included, even ones without a resolvable semver (e.g. "n/a")
    rows.push({ name, version, licenseType, author, workspace })
  })
  return rows
}

function collectDependencies() {
  const byPackage = new Map() // name -> Map<version, { workspaces, licenseType, author }>
  const workspaceDirs = fs.readdirSync(PACKAGES_DIR)
    .filter(d => fs.existsSync(path.join(PACKAGES_DIR, d, 'licences.md')))

  workspaceDirs.forEach(dir => {
    const rows = parseLicencesMd(path.join(PACKAGES_DIR, dir, 'licences.md'), `packages/${dir}`)
    rows.forEach(({ name, version, licenseType, author, workspace }) => {
      if (!byPackage.has(name)) byPackage.set(name, new Map())
      const versions = byPackage.get(name)
      if (!versions.has(version)) versions.set(version, { workspaces: new Set(), licenseType, author })
      versions.get(version).workspaces.add(workspace)
    })
  })

  return byPackage
}

// ─── Step 2: fetch latest version + publish times from the npm registry ──────

function fetchPackageMetadata(name) {
  return new Promise(resolve => {
    const url = `https://registry.npmjs.org/${name}`
    const req = https.get(url, {
      headers: { 'User-Agent': 'unovis-dependency-version-report' },
      timeout: 15000,
    }, res => {
      if (res.statusCode !== 200) {
        res.resume()
        resolve({ name, error: `HTTP ${res.statusCode}` })
        return
      }
      let data = ''
      res.on('data', chunk => { data += chunk })
      res.on('end', () => {
        try {
          const json = JSON.parse(data)
          resolve({
            name,
            latest: json['dist-tags'] && json['dist-tags'].latest,
            time: json.time || {},
          })
        } catch (e) {
          resolve({ name, error: 'Failed to parse registry response' })
        }
      })
    })
    req.on('timeout', () => { req.destroy(new Error('timeout')) })
    req.on('error', err => resolve({ name, error: err.message }))
  })
}

// Simple fixed-size concurrency pool
async function mapWithConcurrency(items, limit, fn) {
  const results = new Array(items.length)
  let cursor = 0
  async function worker() {
    while (cursor < items.length) {
      const i = cursor++
      results[i] = await fn(items[i], i)
    }
  }
  await Promise.all(Array.from({ length: Math.min(limit, items.length) }, worker))
  return results
}

// ─── Step 3: elapsed-time formatting ──────────────────────────────────────────

function formatElapsed(fromDate, toDate) {
  if (!fromDate) return 'unknown'
  const from = new Date(fromDate)
  const to = toDate ? new Date(toDate) : new Date()
  if (isNaN(from.getTime())) return 'unknown'
  const ms = to.getTime() - from.getTime()
  const days = Math.floor(ms / (1000 * 60 * 60 * 24))
  if (days < 0) return '0 days'
  if (days < 30) return `${days} day${days === 1 ? '' : 's'}`
  const years = Math.floor(days / 365)
  const months = Math.floor((days % 365) / 30)
  const parts = []
  if (years > 0) parts.push(`${years} year${years === 1 ? '' : 's'}`)
  if (months > 0) parts.push(`${months} month${months === 1 ? '' : 's'}`)
  if (parts.length === 0) parts.push(`${days} days`)
  return parts.join(', ')
}

// ─── Main ──────────────────────────────────────────────────────────────────────

async function main() {
  if (SHOULD_GATHER_LICENSES) {
    console.log('Running `pnpm gather-licenses` to refresh licences.md files...')
    execSync('pnpm gather-licenses', { cwd: ROOT_DIR, stdio: 'inherit' })
  }

  console.log('Parsing licences.md across all workspaces...')
  const byPackage = collectDependencies()
  const packageNames = Array.from(byPackage.keys()).sort((a, b) => a.localeCompare(b))
  console.log(`Found ${packageNames.length} unique dependencies. Querying npm registry (concurrency=${CONCURRENCY})...`)

  const metadataList = await mapWithConcurrency(packageNames, CONCURRENCY, fetchPackageMetadata)
  const metadataByName = new Map(metadataList.map(m => [m.name, m]))

  const rows = []
  for (const name of packageNames) {
    const versions = byPackage.get(name)
    const meta = metadataByName.get(name)
    // Use the highest resolvable installed version across workspaces as "current";
    // fall back to whatever is listed (e.g. "n/a") if none of them parse as semver
    const allVersions = Array.from(versions.keys())
    const resolvableVersions = allVersions.filter(v => parseSemver(v)).sort(compareSemver)
    const installed = resolvableVersions.length ? resolvableVersions[resolvableVersions.length - 1] : allVersions[0]
    const license = versions.get(installed)
    const isAngularPackage = Array.from(versions.values()).some(version => version.workspaces.has('packages/angular'))
    const usedIn = Array.from(new Set(
      allVersions.flatMap(v => Array.from(versions.get(v).workspaces).map(ws => (allVersions.length > 1 ? `${ws} (${v})` : ws)))
    )).sort()

    if (!parseSemver(installed)) {
      rows.push({
        name, installed, usedIn, licenseType: license.licenseType, author: license.author,
        latest: meta && meta.latest || null, installedDate: null, latestDate: meta && meta.time && meta.time[meta.latest] || null,
        versionsBehind: null, elapsed: 'unknown', error: 'no resolvable installed version',
      })
      continue
    }

    if (!meta || meta.error) {
      rows.push({
        name, installed, usedIn, licenseType: license.licenseType, author: license.author,
        latest: null, installedDate: null, latestDate: null,
        versionsBehind: null, elapsed: 'unknown', error: meta ? meta.error : 'not queried',
      })
      continue
    }

    const time = meta.time || {}
    const installedDate = time[installed] || null
    const latest = meta.latest || installed
    const latestDate = time[latest] || null
    const availableVersions = Object.keys(time)
      .filter(v => parseSemver(v) && !['created', 'modified'].includes(v))
      .filter(v => (isAngularPackage ? compareMinorVersion(v, installed) : compareSemver(v, installed)) > 0)
      .filter(v => (isAngularPackage ? compareMinorVersion(v, latest) : compareSemver(v, latest)) <= 0)
    const versionsBehind = isAngularPackage
      ? new Set(availableVersions.map(v => {
        const parsed = parseSemver(v)
        return `${parsed.major}.${parsed.minor}`
      })).size
      : availableVersions.length

    rows.push({
      name, installed, usedIn, licenseType: license.licenseType, author: license.author,
      latest, installedDate, latestDate, versionsBehind,
      elapsed: formatElapsed(installedDate, null),
    })
  }

  // Most outdated first: unknown status sinks to the bottom
  rows.sort((a, b) => {
    if (a.versionsBehind == null && b.versionsBehind == null) return a.name.localeCompare(b.name)
    if (a.versionsBehind == null) return 1
    if (b.versionsBehind == null) return -1
    return b.versionsBehind - a.versionsBehind
  })

  let gitBranch = 'unknown'
  try { gitBranch = execSync('git rev-parse --abbrev-ref HEAD', { encoding: 'utf8' }).trim() } catch (_) {}

  const reportData = {
    generatedAt: new Date().toISOString(),
    branch: gitBranch,
    totalPackages: rows.length,
    upToDate: rows.filter(r => r.versionsBehind === 0).length,
    behind: rows.filter(r => r.versionsBehind > 0).length,
    unknown: rows.filter(r => r.versionsBehind == null).length,
    rows,
  }

  const reportFileName = `dependency-version-report-${sanitizeForFileName(gitBranch)}-${formatDateForFileName(Date.now())}.html`
  const htmlReportPath = path.join(__dirname, reportFileName)
  fs.writeFileSync(htmlReportPath, generateHtmlReport(reportData))

  console.log(`Done. ${reportData.behind} of ${reportData.totalPackages} dependencies are behind latest (${reportData.unknown} could not be resolved).`)
  console.log(`HTML report saved to: ${htmlReportPath}`)
}

// ─── HTML report ────────────────────────────────────────────────────────────────

function escapeHtml(s) {
  return String(s == null ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')
}

function formatDate(iso) {
  if (!iso) return 'unknown'
  const d = new Date(iso)
  if (isNaN(d.getTime())) return 'unknown'
  return d.toISOString().slice(0, 10)
}

function behindBadgeClass(versionsBehind) {
  if (versionsBehind == null) return 'badge-unknown'
  if (versionsBehind === 0) return 'badge-current'
  if (versionsBehind <= 5) return 'badge-minor'
  return 'badge-major'
}

function generateHtmlReport(data) {
  const workspacePackages = Array.from(new Set(
    data.rows.flatMap(r => r.usedIn.map(ws => ws.replace(/\s+\([^)]*\)$/, '')))
  )).sort()
  const packageOptions = workspacePackages.map(pkg => `<option value="${escapeHtml(pkg)}">${escapeHtml(pkg)}</option>`).join('')
  const rowsHtml = data.rows.map(r => `
        <tr data-status="${r.versionsBehind == null ? 'unknown' : (r.versionsBehind === 0 ? 'current' : 'outdated')}">
          <td class="pkg">${escapeHtml(r.name)}</td>
          <td class="col-license">${escapeHtml(r.licenseType)}</td>
          <td class="col-author">${escapeHtml(r.author)}</td>
          <td>${r.usedIn.map(ws => `<span class="ws">${escapeHtml(ws)}</span>`).join(' ')}</td>
          <td class="mono">${escapeHtml(r.installed)}</td>
          <td class="muted">${escapeHtml(formatDate(r.installedDate))}</td>
          <td class="mono">${escapeHtml(r.latest || 'unknown')}</td>
          <td class="muted">${escapeHtml(formatDate(r.latestDate))}</td>
          <td><span class="badge ${behindBadgeClass(r.versionsBehind)}">${r.versionsBehind == null ? (r.error || 'unknown') : (r.versionsBehind === 0 ? 'up to date' : (r.versionsBehind > 5 ? '5+ versions behind' : 'behind'))}</span></td>
          <td class="muted">${escapeHtml(r.elapsed)}</td>
        </tr>`).join('\n')

  return `<!DOCTYPE html>
<html lang="en" data-theme="dark">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Unovis Dependency Version Report</title>
<style>
  :root {
    --bg: #f6f8fa;
    --surface: #ffffff;
    --surface-2: #f0f3f6;
    --border: #d0d7de;
    --border-subtle: #e4e8ec;
    --text: #1f2328;
    --text-muted: #636c76;
    --accent: #0969da;
    --accent-soft: #0969da14;
    --shadow: 0 1px 3px rgba(27, 31, 36, 0.08), 0 1px 2px rgba(27, 31, 36, 0.06);
    --current-bg: #dafbe1; --current-fg: #1a7f37;
    --minor-bg: #fff8c5; --minor-fg: #9a6700;
    --major-bg: #ffebe9; --major-fg: #cf222e;
    --unknown-bg: #eaeef2; --unknown-fg: #636c76;
  }
  [data-theme="dark"] {
    --bg: #0d1117;
    --surface: #161b22;
    --surface-2: #1c2128;
    --border: #30363d;
    --border-subtle: #21262d;
    --text: #e6edf3;
    --text-muted: #8b949e;
    --accent: #58a6ff;
    --accent-soft: #58a6ff1f;
    --shadow: 0 1px 3px rgba(1, 4, 9, 0.5), 0 8px 24px rgba(1, 4, 9, 0.3);
    --current-bg: #1f6feb26; --current-fg: #7ee787;
    --minor-bg: #9e6a0333; --minor-fg: #e3b341;
    --major-bg: #da363326; --major-fg: #ff7b72;
    --unknown-bg: #30363d; --unknown-fg: #8b949e;
  }
  * { box-sizing: border-box; }
  body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Noto Sans', Helvetica, Arial, sans-serif;
    margin: 0; padding: 32px 24px 64px; background: var(--bg); color: var(--text);
    -webkit-font-smoothing: antialiased; transition: background 0.2s ease, color 0.2s ease;
  }
  .wrap { max-width: 1400px; margin: 0 auto; }
  .header { display: flex; align-items: flex-start; justify-content: space-between; gap: 16px; flex-wrap: wrap; margin-bottom: 8px; }
  h1 { font-size: 22px; font-weight: 600; margin: 0; letter-spacing: -0.01em; }
  .meta { color: var(--text-muted); font-size: 13px; margin-bottom: 24px; line-height: 1.6; }
  .meta strong { color: var(--text); font-weight: 600; }
  .meta code { background: var(--surface-2); border: 1px solid var(--border-subtle); border-radius: 4px; padding: 1px 5px; font-size: 12px; }
  .theme-toggle {
    display: inline-flex; align-items: center; gap: 6px; cursor: pointer; user-select: none;
    background: var(--surface); border: 1px solid var(--border); border-radius: 8px;
    padding: 7px 12px; font-size: 13px; color: var(--text); box-shadow: var(--shadow);
    transition: border-color 0.15s ease, background 0.15s ease;
  }
  .theme-toggle:hover { border-color: var(--accent); }
  .summary { display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 14px; margin-bottom: 24px; }
  .card {
    background: var(--surface); border: 1px solid var(--border); border-radius: 12px;
    padding: 16px 18px; box-shadow: var(--shadow);
  }
  .card .num { display: block; font-size: 28px; font-weight: 700; line-height: 1.1; letter-spacing: -0.02em; }
  .card .label { display: block; font-size: 13px; color: var(--text-muted); margin-top: 4px; }
  .card.accent .num { color: var(--accent); }
  .card.good .num { color: var(--current-fg); }
  .card.bad .num { color: var(--major-fg); }
  .card.warn .num { color: var(--minor-fg); }
  .toolbar {
    display: flex; gap: 12px; margin-bottom: 16px; flex-wrap: wrap; align-items: center;
  }
  .field { position: relative; flex: 1 1 260px; max-width: 380px; }
  .field svg { position: absolute; left: 11px; top: 50%; transform: translateY(-50%); pointer-events: none; opacity: 0.5; }
  input#filter, select {
    font: inherit; font-size: 14px; padding: 9px 12px; background: var(--surface);
    border: 1px solid var(--border); border-radius: 8px; color: var(--text);
    transition: border-color 0.15s ease, box-shadow 0.15s ease; outline: none;
  }
  input#filter { width: 100%; padding-left: 34px; }
  input#filter:focus, select:focus { border-color: var(--accent); box-shadow: 0 0 0 3px var(--accent-soft); }
  select { cursor: pointer; }
  .toggles { display: flex; gap: 8px; flex-wrap: wrap; margin-left: auto; }
  .toggle {
    display: inline-flex; align-items: center; gap: 7px; cursor: pointer; user-select: none;
    background: var(--surface); border: 1px solid var(--border); border-radius: 8px;
    padding: 8px 12px; font-size: 13px; color: var(--text-muted);
    transition: border-color 0.15s ease, color 0.15s ease;
  }
  .toggle:hover { border-color: var(--accent); }
  .toggle input { accent-color: var(--accent); width: 15px; height: 15px; cursor: pointer; margin: 0; }
  .toggle:has(input:checked) { color: var(--text); border-color: var(--accent); }
  .table-wrap {
    background: var(--surface); border: 1px solid var(--border); border-radius: 12px;
    overflow: auto; box-shadow: var(--shadow); max-height: 78vh;
  }
  table { border-collapse: collapse; width: 100%; font-size: 13px; }
  th, td { padding: 11px 14px; text-align: left; vertical-align: top; }
  td { border-top: 1px solid var(--border-subtle); }
  th {
    position: sticky; top: 0; z-index: 1; background: var(--surface-2);
    cursor: pointer; white-space: nowrap; font-weight: 600; color: var(--text-muted);
    font-size: 12px; text-transform: uppercase; letter-spacing: 0.03em;
    border-bottom: 1px solid var(--border); user-select: none;
  }
  th:hover { color: var(--text); }
  th .arrow { opacity: 0; font-size: 10px; margin-left: 4px; }
  th.sort-asc .arrow, th.sort-desc .arrow { opacity: 1; }
  th.sort-desc .arrow::after { content: '▼'; }
  th.sort-asc .arrow::after { content: '▲'; }
  tbody tr { transition: background 0.1s ease; }
  tbody tr:hover { background: var(--accent-soft); }
  .pkg { font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-weight: 600; color: var(--text); }
  .mono { font-family: ui-monospace, SFMono-Regular, Menlo, monospace; }
  .muted { color: var(--text-muted); }
  .ws {
    display: inline-block; background: var(--surface-2); border: 1px solid var(--border-subtle);
    border-radius: 5px; padding: 2px 7px; margin: 1px; font-size: 11px; color: var(--text-muted);
  }
  .badge { display: inline-block; padding: 3px 9px; border-radius: 20px; font-size: 12px; font-weight: 500; white-space: nowrap; }
  .badge-current { background: var(--current-bg); color: var(--current-fg); }
  .badge-minor { background: var(--minor-bg); color: var(--minor-fg); }
  .badge-major { background: var(--major-bg); color: var(--major-fg); }
  .badge-unknown { background: var(--unknown-bg); color: var(--unknown-fg); }
  .empty { padding: 40px; text-align: center; color: var(--text-muted); font-size: 14px; }
  .col-hidden { display: none; }
</style>
</head>
<body>
  <div class="wrap">
    <div class="header">
      <div>
        <h1>Unovis Dependency Version Report</h1>
      </div>
      <label class="theme-toggle" for="theme-switch">
        <span id="theme-icon">🌙</span>
        <span id="theme-label">Dark</span>
        <input type="checkbox" id="theme-switch" hidden>
      </label>
    </div>
    <div class="meta">Generated ${escapeHtml(data.generatedAt)} on branch <strong>${escapeHtml(data.branch)}</strong> &middot; source: each workspace's <code>licences.md</code> &middot; latest versions from the npm registry</div>
    <div class="summary">
      <div class="card accent"><span class="num">${data.totalPackages}</span><span class="label">Total dependencies</span></div>
      <div class="card good"><span class="num">${data.upToDate}</span><span class="label">Up to date</span></div>
      <div class="card bad"><span class="num">${data.behind}</span><span class="label">Behind latest</span></div>
      <div class="card warn"><span class="num">${data.unknown}</span><span class="label">Could not resolve</span></div>
    </div>
    <div class="toolbar">
      <div class="field">
        <svg width="15" height="15" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.6"><circle cx="7" cy="7" r="5"/><line x1="11" y1="11" x2="14" y2="14"/></svg>
        <input id="filter" type="text" placeholder="Filter by dependency name...">
      </div>
      <select id="workspace-filter">
        <option value="">All Unovis packages</option>
        ${packageOptions}
      </select>
      <select id="status-filter">
        <option value="">All statuses</option>
        <option value="outdated">Behind</option>
        <option value="current">Up to date only</option>
        <option value="unknown">Could not resolve only</option>
      </select>
      <div class="toggles">
        <label class="toggle"><input type="checkbox" id="toggle-license"> License type</label>
        <label class="toggle"><input type="checkbox" id="toggle-author"> Author</label>
      </div>
    </div>
    <div class="table-wrap">
      <table id="report">
        <thead>
          <tr>
            <th data-key="name">Package<span class="arrow"></span></th>
            <th data-key="licenseType" class="col-license">License type<span class="arrow"></span></th>
            <th data-key="author" class="col-author">Author<span class="arrow"></span></th>
            <th data-key="usedIn">Used in<span class="arrow"></span></th>
            <th data-key="installed">Installed version<span class="arrow"></span></th>
            <th data-key="installedDate">Installed date<span class="arrow"></span></th>
            <th data-key="latest">Latest version<span class="arrow"></span></th>
            <th data-key="latestDate">Latest date<span class="arrow"></span></th>
            <th data-key="versionsBehind">Status<span class="arrow"></span></th>
            <th data-key="elapsed">Elapsed since installed<span class="arrow"></span></th>
          </tr>
        </thead>
        <tbody>${rowsHtml}
        </tbody>
      </table>
      <div class="empty" id="empty" style="display:none">No dependencies match the current filters.</div>
    </div>
  </div>
  <script>
    (function () {
      const filterEl = document.getElementById('filter')
      const workspaceEl = document.getElementById('workspace-filter')
      const statusEl = document.getElementById('status-filter')
      const emptyEl = document.getElementById('empty')

      const filterRows = () => {
        const q = filterEl.value.toLowerCase()
        const workspace = workspaceEl.value
        const status = statusEl.value
        let visible = 0
        document.querySelectorAll('#report tbody tr').forEach(tr => {
          const matchesName = tr.querySelector('.pkg').textContent.toLowerCase().includes(q)
          const matchesWorkspace = !workspace || Array.from(tr.querySelectorAll('.ws')).some(ws =>
            ws.textContent === workspace || ws.textContent.startsWith(workspace + ' (')
          )
          const matchesStatus = !status || tr.dataset.status === status
          const show = matchesName && matchesWorkspace && matchesStatus
          tr.style.display = show ? '' : 'none'
          if (show) visible++
        })
        emptyEl.style.display = visible === 0 ? '' : 'none'
      }
      filterEl.addEventListener('input', filterRows)
      workspaceEl.addEventListener('change', filterRows)
      statusEl.addEventListener('change', filterRows)

      // Optional columns: License type + Author (hidden by default)
      const setColumn = (className, checked) => {
        document.querySelectorAll('.' + className).forEach(el => el.classList.toggle('col-hidden', !checked))
      }
      const licenseToggle = document.getElementById('toggle-license')
      const authorToggle = document.getElementById('toggle-author')
      licenseToggle.addEventListener('change', () => setColumn('col-license', licenseToggle.checked))
      authorToggle.addEventListener('change', () => setColumn('col-author', authorToggle.checked))
      setColumn('col-license', licenseToggle.checked)
      setColumn('col-author', authorToggle.checked)

      // Sorting
      const tbody = document.querySelector('#report tbody')
      const parseCell = (tr, idx) => {
        const cell = tr.children[idx]
        const text = cell.textContent.trim()
        const num = parseFloat(text.replace(/[^0-9.-]/g, ''))
        return { text, num: isNaN(num) ? null : num }
      }
      document.querySelectorAll('#report th').forEach((th, idx) => {
        th.addEventListener('click', () => {
          const asc = !th.classList.contains('sort-asc')
          document.querySelectorAll('#report th').forEach(h => h.classList.remove('sort-asc', 'sort-desc'))
          th.classList.add(asc ? 'sort-asc' : 'sort-desc')
          const rows = Array.from(tbody.querySelectorAll('tr'))
          rows.sort((a, b) => {
            const va = parseCell(a, idx)
            const vb = parseCell(b, idx)
            let cmp
            if (va.num != null && vb.num != null) cmp = va.num - vb.num
            else cmp = va.text.localeCompare(vb.text, undefined, { numeric: true })
            return asc ? cmp : -cmp
          })
          rows.forEach(r => tbody.appendChild(r))
        })
      })

      // Theme toggle with system preference detection
      const root = document.documentElement
      const themeSwitch = document.getElementById('theme-switch')
      const themeIcon = document.getElementById('theme-icon')
      const themeLabel = document.getElementById('theme-label')
      const prefersDark = window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches
      const applyTheme = dark => {
        root.setAttribute('data-theme', dark ? 'dark' : 'light')
        themeSwitch.checked = dark
        themeIcon.textContent = dark ? '🌙' : '☀️'
        themeLabel.textContent = dark ? 'Dark' : 'Light'
      }
      applyTheme(prefersDark)
      themeSwitch.addEventListener('change', () => applyTheme(themeSwitch.checked))
    })()
  </script>
</body>
</html>
`
}

main().catch(err => {
  console.error('Error generating dependency version report:', err)
  process.exit(1)
})
